window.SAP_CH_DATA = {"id":"ch_36","title":"Picking trên PDA","start_page":343,"end_page":350,"slides":[{"page":343,"text":"Confidential\nSAP PLATINUM PARTNER | CITEK TECHNOLOGY JSC.\n16\n❑App thực hiện: PDA - Picking\nBước 1: \nChọn app Picking trên PDA\nBước 2:\nNgười dùng chọn lệnh xuất \nhàng tổng tương ứng ở màn \nhình Picking\nĐối với thiết bị PDA chuyên \ndụng, người dùng có thể nhấn \nvào nút Scan của máy để quét \nID Pallet/ ID hàng\nĐối với thiết bị điện thoại, \nngười dùng có thể nhấn vào \nnút Camera để quét ID Pallet/ \nID hàng\nĐối với trường hợp gợi ý \nnguyên Pallet, người dùng \nthực hiện quét ID Pallet \nĐối với trường hợp chỉ gợi ý 1 \nphần của ID Pallet, người \ndùng quét ID Pallet mới trước \nvà quét ID hàng sau\nWM.05A.1 – QUY TRÌNH CHUYỂN KHO NỘI BỘ TRONG NHÀ MÁY – CHUYỂN \nNGUYÊN LIỆU (WM) TỪ KHO NGUYÊN LIỆU VỀ KHO XƯỞNG (IM) (CÓ \nBARCODE)\n✓Thực hiện Picking trên PDA","images":["","",""]},{"page":344,"text":"Confidential\nSAP PLATINUM PARTNER | CITEK TECHNOLOGY JSC.\n17\n❑App thực hiện: PDA - Picking\nSau khi người dùng quét ID \nPallet, trên PDA check và ghi \nnhận đủ số lượng so với số \nlượng gợi ý, PDA sẽ hiển thị \nmàu xanh\nWM.05A.1 – QUY TRÌNH CHUYỂN KHO NỘI BỘ TRONG NHÀ MÁY – CHUYỂN \nNGUYÊN LIỆU (WM) TỪ KHO NGUYÊN LIỆU VỀ KHO XƯỞNG (IM) (CÓ \nBARCODE)\n✓Thực hiện Picking trên PDA\nTrường hợp gợi ý nguyên Pallet","images":["",""]},{"page":345,"text":"Confidential\nSAP PLATINUM PARTNER | CITEK TECHNOLOGY JSC.\n18\n❑App thực hiện: PDA - Picking\nNgười dùng tick vào nút Quét \nPallet mới\nThực hiện quét ID Pallet mới \nbằng thiết bị chuyên dụng \nhoặc điện thoại\nSau khi quét Pallet mới, PDA \nhiển thị đã ghi nhận ID Pallet \nmới\nNgười dùng thực hiện quét ID \nhàng, lúc này hệ thống hiểu \ncác ID hàng vừa quét đã nằm \ntrên ID Pallet mới\nSau khi đã hoàn thành quét \ncác trường hợp (nguyên \nPallet/ 1 phần của Pallet), \nngười dùng nhấn nút Chuyển \nSAP để đẩy dữ liệu từ PDA về \nSAP\nWM.05A.1 – QUY TRÌNH CHUYỂN KHO NỘI BỘ TRONG NHÀ MÁY – CHUYỂN \nNGUYÊN LIỆU (WM) TỪ KHO NGUYÊN LIỆU VỀ KHO XƯỞNG (IM) (CÓ \nBARCODE)\n✓Thực hiện Picking trên PDA\nTrường hợp gợi ý 1 phần của Pallet","images":["","",""]},{"page":346,"text":"Confidential\nSAP PLATINUM PARTNER | CITEK TECHNOLOGY JSC.\n19\n❑App thực hiện: Picking\nBước 3:\nNhập app: “Picking” vào \nthanh tìm kiếm\nBước 4: \nClick chọn vào app Picking\nWM.05A.1 – QUY TRÌNH CHUYỂN KHO NỘI BỘ TRONG NHÀ MÁY – CHUYỂN \nNGUYÊN LIỆU (WM) TỪ KHO NGUYÊN LIỆU VỀ KHO XƯỞNG (IM) (CÓ \nBARCODE)\n✓Picking trên SAP","images":[""]},{"page":347,"text":"Confidential\nSAP PLATINUM PARTNER | CITEK TECHNOLOGY JSC.\n20\n❑App thực hiện: Picking\nBước 5: \nĐiền lệnh xuất hàng tổng ở \ntham số để lọc dữ liệu\nBước 6:\nNhấn Go để lọc dữ liệu cần \ntìm \nWM.05A.1 – QUY TRÌNH CHUYỂN KHO NỘI BỘ TRONG NHÀ MÁY – CHUYỂN \nNGUYÊN LIỆU (WM) TỪ KHO NGUYÊN LIỆU VỀ KHO XƯỞNG (IM) (CÓ \nBARCODE)\n✓Picking trên SAP","images":[""]},{"page":348,"text":"Confidential\nSAP PLATINUM PARTNER | CITEK TECHNOLOGY JSC.\n21\n❑App thực hiện: Picking\nBước 7: \nThực hiện chọn tất cả các \ndòng của lệnh xuất hàng tổng \nvừa thực hiện Pick hàng\nBước 8:\nNhấn Check để kiểm tra dữ \nliệu\nBước 9:\nSau khi nhấn Check và dữ liệu \nkhông còn sai sót, tiếp tục \nnhấn Post để tạo giao dịch \ntrên hệ thống\n \nWM.05A.1 – QUY TRÌNH CHUYỂN KHO NỘI BỘ TRONG NHÀ MÁY – CHUYỂN \nNGUYÊN LIỆU (WM) TỪ KHO NGUYÊN LIỆU VỀ KHO XƯỞNG (IM) (CÓ \nBARCODE)\n✓Picking trên SAP","images":[""]},{"page":349,"text":"Confidential\nSAP PLATINUM PARTNER | CITEK TECHNOLOGY JSC.\n22\n❑App thực hiện: Picking\nSau khi người dùng nhấn \nCheck và Post thành công, lúc \nnày tồn kho trên hệ thống đã \nchuyển về vị trí vùng đệm \nxuất, sẵn sàng cho việc phân \nhàng\n✓Xuất kho bán hàng – Kho WM\nWM.05A.1 – QUY TRÌNH CHUYỂN KHO NỘI BỘ TRONG NHÀ MÁY – CHUYỂN \nNGUYÊN LIỆU (WM) TỪ KHO NGUYÊN LIỆU VỀ KHO XƯỞNG (IM) (CÓ \nBARCODE)","images":[""]},{"page":350,"text":"Confidential\nSAP PLATINUM PARTNER | CITEK TECHNOLOGY JSC.\n23\n❑App thực hiện: Picking\nSau khi hoàn thành giao dịch, \ntồn kho được chuyển sang \nvùng đệm xuất\n✓Xuất kho bán hàng – Kho WM\nWM.05A.1 – QUY TRÌNH CHUYỂN KHO NỘI BỘ TRONG NHÀ MÁY – CHUYỂN \nNGUYÊN LIỆU (WM) TỪ KHO NGUYÊN LIỆU VỀ KHO XƯỞNG (IM) (CÓ \nBARCODE)","images":[""]}]};